import{_ as o,o as a,c as d,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/SAMPLE.md","filePath":"manual-zh/SAMPLE.md","lastUpdated":1785684581000}'),t={name:"manual-zh/SAMPLE.md"};function p(l,e,r,S,n,E){return a(),d("div",null,[...e[0]||(e[0]=[c(`<h3 id="_13-3-sample" tabindex="-1">13.3 SAMPLE <a class="header-anchor" href="#_13-3-sample" aria-label="Permalink to &quot;13.3 SAMPLE&quot;">​</a></h3><pre><code>SAMPLE num1 [FROM num2].
</code></pre><p><code>SAMPLE</code> 对活动文件中一定比例个数的个案进行随机抽样。除非它出现在 <code>TEMPORARY</code> 之后，否则它作为转换命令运行，从活动数据集中永久删除个案。</p><p>抽样比例可以表示为 0 到 1 之间的单个数字。若指定的数字为 k，活动数据集中当前选中的个案数为 N，则在 <code>SAMPLE k.</code> 之后，大约选中 k*N 个个案。</p><p>抽样比例也可以按 <code>SAMPLE m FROM N</code> 的形式指定。使用这种形式时，个案的选择方式如下：</p><ol><li>如果 N 等于活动数据集中当前选中的个案数，则恰好选中 m 个个案。</li><li>如果 N 大于活动数据集中当前选中的个案数，则选中等比例的个案。</li><li>如果 N 小于活动数据集中当前选中的个案数，则<em>从活动数据集的前 N 个个案中</em>恰好选中 m 个个案。</li></ol><p><code>SAMPLE</code> 与 <code>SELECT IF</code> 按照语法文件中指定的顺序执行。</p><p>无论语法文件中的顺序如何，<code>SAMPLE</code> 总是在 <code>N OF CASES</code> 之前执行（参见 <a href="./N-OF-CASES">N OF CASES</a>）。</p><p><code>SAMPLE</code> 相同的取值可能产生不同的样本。要获得相同的样本，可在每次 <code>SAMPLE</code> 之前使用 <code>SET</code> 命令将随机数种子设置为相同的值。当文件在处理时所在的系统字节序或浮点格式不同时，仍可能产生不同的样本。默认情况下，随机数种子基于系统时间。</p>`,9)])])}const s=o(t,[["render",p]]);export{m as __pageData,s as default};
